# Copy nested settings so updating one branch does not change the shared prompt definitions.
def crf_assets(profile):
    """Return independent schema and prompt settings for a CRF model."""
    item = copy.deepcopy(CRF[profile])
    config = SimpleNamespace(MODEL=item['config']['model'], PAIR=item['config'],
        CONFIG={'crf': {'discovery_response_format': {'type': 'json_object'}}},
        VALIDATION_FEEDBACK="\nVALIDATOR FEEDBACK: The preceding outputs failed the required output validation. Return a complete corrected JSON using the original source and instructions above. Validation errors: ",
        feedback_purpose=lambda purpose: purpose)
    return item, config

