def synur_assets(profile, training_rows, ontology, training_vectors=()):
    """Bind training rows, the observation ontology and embedding vectors."""
    result=copy.deepcopy(SYNUR)
    result.update(train=training_rows,ontology=ontology,training_vectors=training_vectors)
    if profile=='gpt52':
        result['protocol']['model']='gpt-5.2'
        result['schemas'].update(copy.deepcopy(SYNUR_GPT_SCHEMAS))
    elif profile!='qwen37_plus':
        raise ValueError(profile)
    return result

# Keep stage outputs as replaceable schema slots while binding the training sources.
def synur_induction_inputs(training_rows):
    """Fill discovery request templates with training sources and preceding schemas."""
    documents=[{'document_id':str(d['id']),'text':d['transcript']} for d in training_rows]
    records=[]
    for i,template in enumerate(SYNUR_INDUCTION_TEMPLATES):
        req=copy.deepcopy(template)
        prompt=req['messages'][-1]['content'].replace('__SYNUR_TRAIN_SOURCES__',json.dumps(documents,ensure_ascii=False),1)
        if i:
            prompt=prompt.replace('__SYNUR_PRECEDING_SCHEMA__',json.dumps('__previous_'+str(i-1)+'__',ensure_ascii=False),1)
        req['messages'][-1]['content']=prompt
        records.append({'request':req,'parsed':'__previous_2__' if i==2 else None})
    return {'records':records,'initial_induction':{'schema':'__previous_0__'},
            'function_refinement':{'schema':'__previous_1__'}}

# Introduce structural navigation while keeping clinical decisions grounded in the transcript.
SYNUR_GPT_GUIDE = ('Use the following source organization to navigate the unchanged transcript. Source roles organize '
 'interpretation and do not establish patient facts. Check every source instance in source order, including '
 'instances without a draft observation. Use the exact original wording and its surrounding source context '
 'to resolve subject, time, assertion, and whether text states a finding, interpretation, or instruction. A '
 'mixed statement can express a fact and an action. Do not suppress secondary content because of a role '
 'name, and do not infer a clinical observation from that name. Treat qualifiers as pointers to their exact '
 "source words, not as additional facts. Preserve the task's unchanged observation definitions, extraction "
 'and audit rules, and JSON-array output contract. The repeated source blocks below contain the same '
 'transcript, not extra evidence.')

